// SubjectAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type SubjectAuditPolicy struct {
	_ [0]*Subject
	// Key controls the audit representation of stored foundry_session_subjects.key.
	Key record.Disclosure
	// Scope controls the audit representation of stored foundry_session_subjects.scope.
	Scope record.Disclosure
	// Identity controls the audit representation of stored foundry_session_subjects.identity.
	Identity record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes SubjectChanges) Audit(policy SubjectAuditPolicy) (record.Model[Subject, string], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Subject, string]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Subject, string]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "key", policy.Key)
	if err != nil {
		return record.Model[Subject, string]{}, err
	}
	var captured record.Field[Subject]
	captured, err = record.CaptureField[Subject]("key", codec.String[string](), changes.fields.Key, policy.Key)
	if err != nil {
		return record.Model[Subject, string]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Subject, string]{}, err
	}
	captured, err = record.CaptureField[Subject]("scope", codec.String[string](), changes.fields.Scope, policy.Scope)
	if err != nil {
		return record.Model[Subject, string]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Subject, string]{}, err
	}
	captured, err = record.CaptureField[Subject]("identity", codec.JSON[model.Identity](), changes.fields.Identity, policy.Identity)
	if err != nil {
		return record.Model[Subject, string]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Subject, string]{}, err
	}
	return builder.Build()
}

// SubjectAuditFieldSet contains typed historical fields. An omitted field differs from an absent model or SQL NULL.
type SubjectAuditFieldSet struct {
	_ [0]*Subject
	// Key retains stored foundry_session_subjects.key after write mutators; read accessors do not replace audit values.
	Key foundryvalue.Optional[record.FieldChange[string]]
	// Scope retains stored foundry_session_subjects.scope after write mutators; read accessors do not replace audit values.
	Scope foundryvalue.Optional[record.FieldChange[string]]
	// Identity retains stored foundry_session_subjects.identity after write mutators; read accessors do not replace audit values.
	Identity foundryvalue.Optional[record.FieldChange[foundryvalue.JSON[model.Identity]]]
}

// SubjectAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func SubjectAuditFields(history record.Model[Subject, string]) (SubjectAuditFieldSet, error) {
	view, err := record.Inspect(history)
	if err != nil {
		return SubjectAuditFieldSet{}, err
	}
	var fields SubjectAuditFieldSet
	fields.Key, err = record.ReadField(view, "key", codec.String[string]())
	if err != nil {
		return SubjectAuditFieldSet{}, err
	}
	fields.Scope, err = record.ReadField(view, "scope", codec.String[string]())
	if err != nil {
		return SubjectAuditFieldSet{}, err
	}
	fields.Identity, err = record.ReadField(view, "identity", codec.JSON[model.Identity]())
	if err != nil {
		return SubjectAuditFieldSet{}, err
	}
	return fields, nil
}

// SubjectAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func SubjectAuditing(policy SubjectAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Subject]()
		if err != nil {
			return err
		}
		return RegisterSubjectObserver(registrar, pool, NewSubjectObserver(name), func(resolver foundation.Resolver) (func() SubjectHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() SubjectHooks {
				write := func(ctx context.Context, tx *database.Tx, changes SubjectChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return SubjectHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
